// Prepare content generation request
const promptSelector = require('/home/node/.n8n/custom/functions/promptSelector.js');
const aiRouter = require('/home/node/.n8n/custom/functions/aiRouter.js');

// Get prompt from cache
const prompts = global.prompts || {};
const platform = items[0].json.platform || 'twitter';
const contentType = items[0].json.content_type || 'general';

// Handle revision requests
if (items[0].json.needs_revision) {
  items[0].json.revision_attempt = (items[0].json.revision_attempt || 0) + 1;
  items[0].json.preferred_model = items[0].json.retry_with_model;
}

// Get appropriate prompt
let contentPrompt;
try {
  contentPrompt = promptSelector.select('Content_Prompts', platform, contentType, {
    prompts,
    variables: {
      TOPIC: items[0].json.idea || items[0].json.topic,
      INDUSTRY: items[0].json.industry || 'general',
      HASHTAGS: items[0].json.research_data?.keywords?.map(k => k.tag || k.keyword).join(', ') || ''
    }
  });
} catch (error) {
  contentPrompt = {
    prompt: `Create engaging ${platform} content about ${items[0].json.idea}`,
    characterLimit: 1000,
    tone: 'conversational',
    aiModel: 'gpt-4o-mini'
  };
}

// Route to appropriate AI model
const routing = aiRouter.route(items[0].json.idea, {
  content_type: contentType,
  platform: platform,
  complexity: items[0].json.complexity || 'medium',
  word_count: contentPrompt.characterLimit / 5,
  max_cost: items[0].json.needs_revision ? 0.20 : 0.10,
  preferred_model: items[0].json.preferred_model || contentPrompt.aiModel
});

// Check if video is needed
const needsVideo = ['tiktok', 'instagram', 'youtube'].includes(platform);
const needsImage = ['instagram', 'facebook', 'linkedin'].includes(platform) && !needsVideo;

return [{
  json: {
    ...items[0].json,
    content_prompt: contentPrompt,
    ai_routing: routing,
    needs_video: needsVideo,
    needs_image: needsImage,
    generation_config: {
      prompt: contentPrompt.prompt,
      model: routing.model,
      temperature: routing.config.temperature,
      max_tokens: routing.config.max_tokens,
      platform: platform
    }
  }
}];

// Merge text results from different models
const openAIResult = $items('OpenAI Generate')?.[0]?.json;
const claudeResult = $items('Claude Generate')?.[0]?.json;
const geminiResult = $items('Gemini Generate')?.[0]?.json;
const groqResult = $items('Groq Generate')?.[0]?.json;

let generatedText = '';
let sourceModel = '';

// Extract text based on model response format
if (openAIResult?.choices?.[0]?.message?.content) {
  generatedText = openAIResult.choices[0].message.content;
  sourceModel = 'openai';
} else if (claudeResult?.content?.[0]?.text) {
  generatedText = claudeResult.content[0].text;
  sourceModel = 'claude';
} else if (geminiResult?.candidates?.[0]?.content?.parts?.[0]?.text) {
  generatedText = geminiResult.candidates[0].content.parts[0].text;
  sourceModel = 'gemini';
} else if (groqResult?.choices?.[0]?.message?.content) {
  generatedText = groqResult.choices[0].message.content;
  sourceModel = 'groq';
}

if (!generatedText) {
  throw new Error('No text generated from any model');
}

// Apply character limit
const charLimit = items[0].json.content_prompt.characterLimit || 1000;
if (generatedText.length > charLimit) {
  generatedText = generatedText.substring(0, charLimit - 3) + '...';
}

return [{
  json: {
    ...items[0].json,
    generated_content: generatedText,
    content_source: sourceModel,
    content_length: generatedText.length,
    generation_cost: items[0].json.ai_routing.estimated_cost
  }
}];

// Compile all generated assets
const textResult = items[0].json;
const imageResult = $items('Generate Image')?.[0]?.json;
const videoResult = $items('Execute Video Generation')?.[0]?.json;

const output = {
  ...textResult,
  generated_text: textResult.generated_content,
  platform: textResult.platform,
  content_type: textResult.content_type || 'general'
};

// Add image if generated
if (imageResult?.image_url) {
  output.image_url = imageResult.image_url;
  output.media_url = imageResult.image_url;
  output.has_image = true;
}

// Add video if generated
if (videoResult?.outputs?.video_ready) {
  output.video_url = videoResult.outputs.video_url;
  output.video_script = videoResult.outputs.script;
  output.thumbnail_url = videoResult.outputs.thumbnail_url;
  output.has_video = true;
  output.video_source = videoResult.outputs.video_source;
}

// Calculate total cost
output.total_generation_cost = textResult.generation_cost + 
  (videoResult?.outputs?.generation_cost || 0) + 
  (imageResult ? 0.04 : 0); // DALL-E 3 cost

// Add best posting time from scheduler
const smartScheduler = require('/home/node/.n8n/custom/functions/smartScheduler.js');
const scheduling = smartScheduler.calculateBestTime(output.platform, {
  target_timezone: process.env.TARGET_TIMEZONE || 'America/New_York',
  content_type: output.content_type
});

output.best_time = scheduling.best_time;
output.scheduling_score = scheduling.score;
output.scheduling_reason = scheduling.reasoning;

// Success response
return [{
  json: output,
  binary: videoResult?.binary || {}
}];
